// Special flow for Bukhara/Pravda kitchen receipt.
(function(){
 state.kitchenSupplyDishes=[];state.kitchenSupplyQty={};state.kitchenSupplyBusy=false;state.kitchenSupplyLoadedFor='';state.kitchenSupplyOpenGroups={};state.kitchenSupplySearch='';
 function currentBusinessDate(){try{return state.home?.businessDate||businessDate()||''}catch{return state.home?.businessDate||''}}
 function cfg(){if(state.point==='BUKHARA')return {source:'Бухара Кухня',target:'Бухара раздача',transfer:true,test:true};if(state.point==='PRAVDA'){const after=currentBusinessDate()>='2026-09-25';return after?{source:'Правда Кухня',target:'Правда раздача',transfer:true}:{source:'Правда Кухня',target:'Правда Кухня',transfer:false};}return null}
 function employeeActor(){return localStorage.getItem('stolovaya:employee-name')||sessionStorage.getItem('stolovaya:employee-name')||'Буфетчик'}
 const baseHome=homeScreen;homeScreen=function(){let html=baseHome();const c=cfg();if(!c)return html;return html.replace(/<button data-screen="transfer"[^>]*>[\s\S]*?<\/button>/,`<button type="button" id="kitchen-supply-open" ${state.home?.submitted||state.home?.dayClosed?'disabled':''}><span>⇩</span><div><b>Получить с кухни</b></div></button>`)};
 async function openKitchenSupply(){const c=cfg();if(!c||state.home?.submitted||state.home?.dayClosed)return;state.screen='kitchen-supply';state.message='';state.kitchenSupplyOpenGroups={};state.kitchenSupplySearch='';render();state.kitchenSupplyBusy=true;render();try{state.kitchenSupplyDishes=await rpc('public_kitchen_supply_dishes',{p_token:state.token,p_point_code:state.point,p_business_date:currentBusinessDate()||businessDate()});state.kitchenSupplyLoadedFor=`${state.point}:${currentBusinessDate()}`}catch(e){state.message=e.message||'Не удалось загрузить блюда'}finally{state.kitchenSupplyBusy=false;render()}}
 function selectedRows(){return(state.kitchenSupplyDishes||[]).filter(x=>n(state.kitchenSupplyQty[x.dishId])>0)}
 function norm(s){return clean(s||'').toLocaleLowerCase('ru-RU').replace(/ё/g,'е')}
 function filteredDishes(){const q=norm(state.kitchenSupplySearch).trim();if(!q)return state.kitchenSupplyDishes||[];const words=q.split(/\s+/).filter(Boolean);return(state.kitchenSupplyDishes||[]).filter(x=>{const hay=norm(`${x.name||''} ${x.code||''} ${x.group||''}`);return words.every(w=>hay.includes(w))})}
 function groups(){const m={};filteredDishes().forEach(x=>{const g=clean(x.group||'Прочее')||'Прочее';(m[g]||(m[g]=[])).push(x)});return Object.keys(m).sort((a,b)=>a.localeCompare(b,'ru')).map(name=>({name,items:m[name].sort((a,b)=>clean(a.name).localeCompare(clean(b.name),'ru'))}))}
 function qtyText(v){const q=n(v);return Number.isInteger(q)?String(q):String(Math.round(q*1000)/1000).replace('.',',')}
 function kitchenSupplyScreen(){const c=cfg();if(!c)return `${header()}${back('Получить с кухни')}<div class="notice">Эта операция доступна только на Бухаре и Правде.</div>`;const chosen=selectedRows();const hint=c.test?'Можно получать с кухни несколько раз за день. Каждое новое получение <b>добавится в одно общее перемещение Бухара Кухня → Бухара раздача</b>. Акт приготовления сформируем по итогам закрытия дня.':'';const list=groups();const searching=!!norm(state.kitchenSupplySearch).trim();return `${header()}${back('Получить с кухни')}<section class="question-card kitchen-source"><h2>${esc(c.source)} → ${esc(c.target)}</h2><p>${hint}</p></section><div class="kitchen-search"><input id="kitchen-supply-search" type="search" autocomplete="off" placeholder="Поиск блюда по нескольким буквам" value="${esc(state.kitchenSupplySearch||'')}"></div>${state.kitchenSupplyBusy&&!list.length?'<div class="notice">Загружаем блюда…</div>':searching&&!list.length?'<div class="notice">Ничего не найдено</div>':`<div class="kitchen-groups">${list.map(g=>{const open=searching||!!state.kitchenSupplyOpenGroups[g.name];const count=g.items.filter(x=>n(state.kitchenSupplyQty[x.dishId])>0).length;return `<section class="kitchen-group"><button type="button" class="kitchen-group-head" data-kitchen-group="${esc(g.name)}"><span>${esc(g.name)}</span><span class="kitchen-group-meta">${count?`выбрано ${count} · `:''}${open?'▲':'▼'}</span></button>${open?`<div class="kitchen-group-body">${g.items.map(x=>`<div class="kitchen-dish"><div class="kitchen-dish-name"><b>${esc(clean(x.name))}</b>${x.code?`<small>${esc(x.code)}</small>`:''}<small class="kitchen-available">Доступно: <b>${esc(qtyText(x.availableQty))}</b></small></div><input data-kitchen-supply="${x.dishId}" inputmode="decimal" placeholder="0" value="${esc(state.kitchenSupplyQty[x.dishId]||'')}"></div>`).join('')}</div>`:''}</section>`}).join('')}</div>`}<div class="sticky-action"><button id="kitchen-supply-send" class="primary" ${state.kitchenSupplyBusy||!chosen.length?'disabled':''}>${state.kitchenSupplyBusy?'Проводим…':`Добавить к получению${chosen.length?` · ${chosen.length}`:''}`}</button></div>${state.message?`<p class="toast">${esc(state.message)}</p>`:''}`}
 async function sendKitchenSupply(){if(state.kitchenSupplyBusy)return;const items=selectedRows().map(x=>({dishId:x.dishId,quantity:n(state.kitchenSupplyQty[x.dishId])}));if(!items.length)return;if(!confirm(`Добавить получение с кухни?\nПозиций: ${items.length}`))return;state.kitchenSupplyBusy=true;state.message='';render();try{const r=await rpc('public_receive_from_kitchen',{p_token:state.token,p_point_code:state.point,p_items:items,p_actor:employeeActor(),p_business_date:currentBusinessDate()||businessDate()});state.kitchenSupplyQty={};state.kitchenSupplyOpenGroups={};state.kitchenSupplySearch='';await loadPoint();state.kitchenSupplyLoadedFor='';state.screen='home';state.message=r.accumulated?`Получение добавлено в общее перемещение ${r.transferDocument}.`:'Получение проведено.'}catch(e){state.message=e.message||'Не удалось провести получение'}finally{state.kitchenSupplyBusy=false;render()}}
 const baseRender=render;render=function(){if(state.screen==='kitchen-supply'){app.innerHTML=kitchenSupplyScreen();bind();return}baseRender()};
 const baseBind=bind;bind=function(){baseBind();document.getElementById('kitchen-supply-open')?.addEventListener('click',openKitchenSupply);const search=document.getElementById('kitchen-supply-search');if(search){search.oninput=e=>{state.kitchenSupplySearch=e.target.value;const pos=e.target.selectionStart;render();const next=document.getElementById('kitchen-supply-search');if(next){next.focus();try{next.setSelectionRange(pos,pos)}catch{}}}}document.querySelectorAll('[data-kitchen-group]').forEach(b=>b.onclick=()=>{if(norm(state.kitchenSupplySearch).trim())return;const g=b.dataset.kitchenGroup;state.kitchenSupplyOpenGroups[g]=!state.kitchenSupplyOpenGroups[g];render()});document.querySelectorAll('[data-kitchen-supply]').forEach(inp=>inp.oninput=e=>{const v=e.target.value.replace(',','.');if(v&&!/^\d*(\.\d{0,3})?$/.test(v)){e.target.value=state.kitchenSupplyQty[inp.dataset.kitchenSupply]||'';return}state.kitchenSupplyQty[inp.dataset.kitchenSupply]=v;const btn=document.getElementById('kitchen-supply-send');if(btn){const cnt=selectedRows().length;btn.disabled=!cnt;btn.textContent=`Добавить к получению${cnt?` · ${cnt}`:''}`}});document.getElementById('kitchen-supply-send')?.addEventListener('click',sendKitchenSupply)};
 const style=document.createElement('style');style.textContent=`.kitchen-source{margin-bottom:12px}.kitchen-source h2{margin-bottom:6px}.kitchen-search{margin:0 0 12px}.kitchen-search input{box-sizing:border-box;width:100%;border:1px solid #cfd7d1;border-radius:14px;background:#fff;padding:14px 16px;font-size:17px;color:#24372d;outline:none}.kitchen-search input:focus{border-color:#5d806d;box-shadow:0 0 0 3px rgba(93,128,109,.12)}.kitchen-groups{display:flex;flex-direction:column;gap:9px;margin-bottom:90px}.kitchen-group{background:#fff;border:1px solid #d8ddd9;border-radius:16px;overflow:hidden}.kitchen-group-head{width:100%;border:0;background:#fff;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 18px;text-align:left;font-size:18px;font-weight:800;color:#24372d}.kitchen-group-meta{font-size:14px;font-weight:600;color:#6e7771;white-space:nowrap}.kitchen-group-body{border-top:1px solid #edf0ed}.kitchen-dish{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 14px;border-bottom:1px solid #edf0ed}.kitchen-dish:last-child{border-bottom:0}.kitchen-dish-name{display:flex;flex-direction:column;min-width:0}.kitchen-dish-name b{font-size:16px}.kitchen-dish-name small{margin-top:3px;color:#7a817d}.kitchen-dish-name .kitchen-available{margin-top:5px;color:#557064;font-size:13px}.kitchen-dish-name .kitchen-available b{font-size:13px}.kitchen-dish input{width:82px;min-width:82px;text-align:center;font-size:18px}`;document.head.appendChild(style);
})();